const cameraDirectory={data:[],primary:[],query:'',provider:'all',page:0,players:[],loaded:false};
const cameraCoins={fremont:{name:'Freightwatch',ticker:'FREIGHT',symbol:'F',brief:'Watch the I-80 corridor for changing traffic density, visible obstructions and low visibility',color:'#e8edd6'},'sixth-street':{name:'Sixth Signal',ticker:'SIXTH',symbol:'S',brief:'Observe road access and visible traffic conditions at 6th Street',color:'#dde7ea'},newbridge:{name:'Bridgewatch',ticker:'BRIDGE',symbol:'B',brief:'Observe visible obstructions, smoke and road conditions at Newbridge Street',color:'#ece4d9'},'tower-bridge':{name:'London Lens',ticker:'LENS',symbol:'L',brief:'Look for road obstructions and visible changes at Tower Bridge without identifying people',color:'#e4e1ed'},woodlands:{name:'Causeway',ticker:'CAUSE',symbol:'C',brief:'Observe the Woodlands Causeway for visible traffic buildup and road conditions',color:'#e5ecdb'},inkoo:{name:'Nordic Eye',ticker:'NORD',symbol:'N',brief:'Watch Road 51 for snow, visibility changes, water and road obstructions',color:'#dfe7eb'}};
let tokenPanel=null,tokenCamera=null,tokenMission=null,tokenUpdateTimer=null;
const tokenPage=document.createElement('section');tokenPage.id='token-page';document.querySelector('main').append(tokenPage);
function cameraCoin(camera){const draft=drafts.find(d=>d.cameraId===camera.id);return draft||{id:'camera-'+camera.id,...(cameraCoins[camera.id]||{name:camera.name,ticker:'CAM'+String(cameraDirectory.data.indexOf(camera)+1).padStart(4,'0'),symbol:'◎',brief:'Observe visible road and weather conditions at '+camera.name,color:'#e6ecdc'}),cameraId:camera.id,region:camera.region,modelId:liveState.status?.defaultModel||'google/gemma-3-4b-it',draft:false};}
function exitToken(){document.body.classList.remove('token-mode');tokenPanel?.destroy();tokenPanel=null;tokenCamera=null;clearInterval(tokenUpdateTimer);if(location.hash.startsWith('#/coin/'))history.replaceState(null,'','#');}
function tokenHome(){exitToken();showHome();window.scrollTo({top:0,behavior:'instant'});}
function openCameraToken(cameraId,missionOverride=null){
  const camera=cameraDirectory.data.find(c=>c.id===cameraId)||liveState.cameras.find(c=>c.id===cameraId);if(!camera)return;
  tokenPanel?.destroy();clearInterval(tokenUpdateTimer);tokenCamera=camera;tokenMission=missionOverride||cameraCoin(camera);const m=tokenMission,model=catalog.data.find(v=>v.id===m.modelId)||catalog.data.find(v=>v.id===liveState.status.defaultModel);
  cameraDirectory.players.forEach(p=>p.destroy());cameraDirectory.players=[];liveState.players.forEach(p=>p.destroy());
  if(!liveState.cameras.some(c=>c.id===camera.id))liveState.cameras.push(camera);
  showHome();document.body.classList.add('token-mode');if(location.hash!=='#/coin/'+camera.id)history.pushState(null,'','#/coin/'+camera.id);window.scrollTo({top:0,behavior:'instant'});
  tokenPage.innerHTML='<button class="token-back" id="token-back">← All camera coins</button><div class="token-identity"><span class="token-symbol" style="background:'+escapeHtml(m.color||'#e6ebdd')+'">'+escapeHtml(m.symbol||m.name[0])+'</span><div><h1>$'+escapeHtml(m.ticker)+' <span>'+escapeHtml(m.name)+'</span></h1><p>'+escapeHtml(m.brief)+'</p></div><span class="token-state">'+(m.draft?'LOCAL DRAFT':'MISSION CONCEPT')+'</span></div><div class="token-owner"><span>'+(m.walletAddress?'Connected creator wallet '+escapeHtml(m.walletAddress.slice(0,6)+'…'+m.walletAddress.slice(-4)):'Unclaimed mission · no creator assigned')+'</span><span id="token-mint-status">No coin issued</span></div><div class="token-stats"><div><span>MARKET CAP</span><strong id="token-mcap">Not launched</strong><small id="token-market-time">Connect an existing mint below</small></div><div><span>COMPUTE</span><strong>$1 / day</strong><small>Shared local spend guard</small></div><div><span>FEES CLAIMED</span><strong>—</strong><small>No fee contract deployed</small></div><div><span>CAMERA COMPUTE SPENT</span><strong id="token-spent">—</strong><small id="token-tokens">Saved observations</small></div><div><span>24H VOLUME</span><strong id="token-volume">—</strong><small>Requires a traded token</small></div><div><span>OBSERVATIONS</span><strong id="token-observations">0</strong><small id="token-monitor-state">Checking monitor</small></div></div><div class="token-camera-address"><span>▧ '+escapeHtml(camera.name)+' / '+escapeHtml(camera.city)+'</span><a href="'+escapeHtml(camera.source)+'" target="_blank" rel="noopener">Official source ↗</a></div><div id="token-observer"></div><div class="token-lower"><section class="token-findings"><div class="token-section-heading"><h2>What the agent is looking for</h2><span>MISSION BRIEF</span></div><p>'+escapeHtml(m.brief)+'</p><div class="watch-topics"><span>Visible scene changes</span><span>Road obstructions</span><span>Possible smoke or flooding</span><span>Visibility conditions</span></div><div class="token-purpose">Reported theft or damage can be added to an authorized mission brief · A camera observation does not establish a crime or identify a suspect</div><div class="token-section-heading"><h2>Findings & evidence</h2><span id="token-findings-count">LOADING</span></div><div id="token-findings-list"></div></section><aside class="token-model"><h2>Model</h2><button class="token-model-link" data-preview-model="'+escapeHtml(model.id)+'">'+logoHtml(model.id)+'<span><b>'+escapeHtml(modelName(model))+'</b><small>via OpenRouter</small></span><span>↗</span></button><div class="token-model-prices"><span>INPUT '+tokenPrice(model.pricing.prompt)+'/M</span><span>OUTPUT '+tokenPrice(model.pricing.completion)+'/M</span></div><h2>Source & coverage</h2><p>'+escapeHtml(camera.provider)+'<br>'+escapeHtml(camera.stream?'Continuous provider video':camera.videoClip?'Short video clips · refreshed about every '+camera.interval/60+' minutes':'Provider image · every '+camera.interval/60+' minutes')+'</p><p class="token-detail-note">Images retain their original framing and source timestamps · Availability depends on the provider</p><button class="button primary" id="token-create">Create a mission for this camera ↗</button><details class="token-market-link"><summary>Connect an existing Solana token</summary><p>Track public market data for a mint · This does not establish ownership or deploy a coin</p><form id="token-market-form"><input aria-label="Solana token mint" placeholder="Solana mint address" pattern="[1-9A-HJ-NP-Za-km-z]{32,44}" required><button class="button" type="submit">Link market data</button></form><div id="token-market-message" role="status"></div></details></aside></div>';
  document.querySelector('#token-back').onclick=()=>{tokenHome();renderCameraDirectory();};
  if(m.draft){const del=document.createElement('button');del.className='text-button';del.textContent='Delete local draft';del.onclick=()=>{try{const next=drafts.filter(d=>d.id!==m.id);localStorage.setItem('parallax-drafts',JSON.stringify(next));drafts=next;renderRows();openCameraToken(camera.id);}catch{del.textContent='Could not delete draft';}};document.querySelector('.token-model').append(del);}document.querySelector('#token-create').onclick=()=>openLaunch({...m,cameraId:camera.id,region:regions.some(r=>r.id===camera.region)?camera.region:'california'});
  tokenPanel=createObserver(document.querySelector('#token-observer'),{cameraId:camera.id,modelId:model.id,brief:m.brief,autorun:false});
  document.querySelector('#token-market-form').onsubmit=async e=>{e.preventDefault();const mint=e.target.querySelector('input').value.trim();try{localStorage.setItem('parallax-token-'+camera.id,mint);}catch{}await loadTokenMarket(mint,camera.id);};
  let savedMint;try{savedMint=localStorage.getItem('parallax-token-'+camera.id);}catch{}if(savedMint){document.querySelector('#token-market-form input').value=savedMint;loadTokenMarket(savedMint,camera.id);}
  updateTokenFindings();tokenUpdateTimer=setInterval(updateTokenFindings,10000);
}
async function loadTokenMarket(mint,cameraId){const message=document.querySelector('#token-market-message');message.textContent='Checking DEX Screener';try{const response=await fetch('/api/market/'+encodeURIComponent(mint));if(!response.ok)throw new Error('Market data unavailable');const data=await response.json();if(tokenCamera?.id!==cameraId)return;document.querySelector('#token-mcap').textContent=data.marketCap==null?'Unavailable':'$'+Number(data.marketCap).toLocaleString('en-US',{notation:'compact',maximumFractionDigits:2});document.querySelector('#token-volume').textContent=data.volume24h==null?'—':'$'+Number(data.volume24h).toLocaleString('en-US',{notation:'compact',maximumFractionDigits:2});document.querySelector('#token-market-time').textContent='DEX Screener · '+liveTime(data.checkedAt);document.querySelector('#token-mint-status').textContent='Tracking '+mint.slice(0,6)+'…'+mint.slice(-4);message.innerHTML=data.found?'Market data connected'+(data.url?' · <a target="_blank" rel="noopener" href="'+escapeHtml(data.url)+'">View pair ↗</a>':''):'No supported trading pair found for this mint';}catch{if(tokenCamera?.id===cameraId)message.textContent='Market data unavailable · try again';}}
async function updateTokenFindings(){if(!tokenCamera||document.hidden)return;const id=tokenCamera.id;try{const response=await fetch('/api/monitor?camera='+encodeURIComponent(id));if(!response.ok)return;const data=await response.json();if(tokenCamera?.id!==id)return;const list=data.history.filter(r=>r.evidence.camera===id);const total=data.cameraTotals;document.querySelector('#token-spent').textContent=liveMoney(total?.cost??list.reduce((sum,r)=>sum+(r.cost||0),0));document.querySelector('#token-tokens').textContent=(total?.tokens??list.reduce((sum,r)=>sum+(r.tokens||0),0)).toLocaleString()+' tokens · retained records';document.querySelector('#token-observations').textContent=total?.count??list.length;document.querySelector('#token-monitor-state').textContent=cameraDirectory.primary.some(c=>c.id===id)?(data.enabled?'Background checks active':'Background checks paused'):'On-demand observation';document.querySelector('#token-findings-count').textContent=list.length+' SAVED';document.querySelector('#token-findings-list').innerHTML=list.length?list.map(r=>'<button class="token-finding" data-token-report="'+escapeHtml(r.id)+'"><span>'+liveTime(r.completedAt)+' · '+escapeHtml(r.model)+'</span><p>'+escapeHtml(r.text)+'</p><small>Original frame + source + uncertainty ↗</small></button>').join(''):'<div class="token-empty">The first observation will appear here after the agent reviews this camera</div>';document.querySelectorAll('[data-token-report]').forEach(b=>b.onclick=()=>inspectObservation(list.find(r=>r.id===b.dataset.tokenReport)));}catch{}}
function renderCameraDirectory(){if(!cameraDirectory.loaded||document.body.classList.contains('token-mode')||document.body.classList.contains('devnet-mode'))return;cameraDirectory.players.forEach(p=>p.destroy());cameraDirectory.players=[];const q=cameraDirectory.query.toLowerCase();const list=cameraDirectory.data.filter(c=>(cameraDirectory.provider==='all'||c.provider===cameraDirectory.provider)&&(!q||[c.name,c.city,c.provider,c.region].join(' ').toLowerCase().includes(q)));const start=cameraDirectory.page*12,visible=list.slice(start,start+12);document.querySelector('#camera-directory-count').textContent=list.length.toLocaleString()+' provider-listed cameras';document.querySelector('#live-wall').innerHTML=visible.map(c=>{const coin=cameraCoin(c);return '<article class="camera-coin-card"><button class="camera-open" data-camera-token="'+escapeHtml(c.id)+'" aria-label="Open '+escapeHtml(coin.name)+' camera token"><div class="directory-camera-preview" data-directory-camera="'+escapeHtml(c.id)+'"><div class="directory-camera-placeholder">'+(c.stream?'LIVE VIDEO':c.videoClip?'VIDEO CLIPS':'REFRESHING IMAGE')+'</div></div><div class="camera-coin-label"><span class="coin-avatar" style="background:'+escapeHtml(coin.color||'#e5ebdb')+'">'+escapeHtml(coin.symbol||'◎')+'</span><span><b>$'+escapeHtml(coin.ticker)+'</b><small>'+escapeHtml(c.name)+'</small></span><span class="camera-coin-arrow">↗</span></div></button><div class="camera-coin-bottom"><span>'+escapeHtml(c.city||c.provider)+'</span><span>'+(coin.draft?'Your draft':'Mission concept')+'</span></div></article>';}).join('');document.querySelector('#camera-page-label').textContent=list.length?(start+1)+'–'+Math.min(start+12,list.length)+' of '+list.length.toLocaleString():'No matching cameras';document.querySelector('#camera-prev').disabled=cameraDirectory.page===0;document.querySelector('#camera-next').disabled=start+12>=list.length;document.querySelectorAll('[data-camera-token]').forEach(b=>b.onclick=()=>openCameraToken(b.dataset.cameraToken));const visibility=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const host=entry.target,camera=cameraDirectory.data.find(c=>c.id===host.dataset.directoryCamera);if(!host.dataset.loaded){host.dataset.loaded='true';const player=createCameraPlayer(host,camera);host.querySelector('video')?.removeAttribute('controls');cameraDirectory.players.push(player);}visibility.unobserve(host);}},{rootMargin:'100px'});document.querySelectorAll('[data-directory-camera]').forEach(h=>visibility.observe(h));}
async function initializeTokenDirectory(){cameraDirectory.primary=[...liveState.cameras];document.querySelector('#main-observer')?.remove();liveState.main?.destroy();liveState.main=null;liveState.players.forEach(p=>p.destroy());document.querySelector('.live-heading h2').innerHTML='Every camera has a mission<br><span>Every mission has a coin</span>';document.querySelector('.live-heading p').textContent='Explore public cameras, open a mission, and see what its agent observes';document.querySelector('.live-wall-heading').remove();document.querySelector('#live-wall').insertAdjacentHTML('beforebegin','<div class="camera-directory-tools"><label><input type="search" id="camera-directory-search" placeholder="Search cameras, cities or countries" aria-label="Search camera directory"></label><select id="camera-provider-filter" aria-label="Camera provider"><option value="all">All camera sources</option></select><span id="camera-directory-count">Loading official catalogs</span></div>');document.querySelector('#live-wall').insertAdjacentHTML('afterend','<div class="camera-pagination"><span id="camera-page-label"></span><div><button class="button small" id="camera-prev">← Previous</button><button class="button small" id="camera-next">Next →</button></div></div><p class="camera-directory-note">Official provider catalogs · Cameras may go offline · Live video where supplied, otherwise refreshed source images · Background analysis currently covers the six featured cameras</p>');
  try{const response=await fetch('/api/camera-catalog');if(!response.ok)throw new Error();const payload=await response.json();cameraDirectory.data=payload.data;}catch{cameraDirectory.data=[...liveState.cameras];}
  cameraDirectory.loaded=true;const providers=[...new Set(cameraDirectory.data.map(c=>c.provider))];document.querySelector('#camera-provider-filter').innerHTML='<option value="all">All camera sources</option>'+providers.map(p=>'<option>'+escapeHtml(p)+'</option>').join('');document.querySelector('#camera-directory-search').oninput=e=>{cameraDirectory.query=e.target.value;cameraDirectory.page=0;renderCameraDirectory();};document.querySelector('#camera-provider-filter').onchange=e=>{cameraDirectory.provider=e.target.value;cameraDirectory.page=0;renderCameraDirectory();};document.querySelector('#camera-prev').onclick=()=>{cameraDirectory.page--;renderCameraDirectory();};document.querySelector('#camera-next').onclick=()=>{cameraDirectory.page++;renderCameraDirectory();};renderCameraDirectory();routeCameraToken();}
function routeCameraToken(){if(!cameraDirectory.loaded)return;const match=/^#\/coin\/([a-zA-Z0-9._-]+)$/.exec(location.hash);if(match)openCameraToken(match[1]);else if(document.body.classList.contains('token-mode')){exitToken();renderCameraDirectory();}}
window.addEventListener('hashchange',routeCameraToken);window.addEventListener('popstate',routeCameraToken);window.addEventListener('parallax-ready',initializeTokenDirectory,{once:true});
document.querySelectorAll('.brand,[data-nav],#models-nav').forEach(b=>b.addEventListener('click',()=>{if(document.body.classList.contains('token-mode')){exitToken();renderCameraDirectory();}},{capture:true}));
openMission=id=>{const mission=[...drafts,...missions].find(m=>m.id===id);if(!mission)return;const camera=cameraDirectory.data.find(c=>c.id===mission.cameraId)||cameraDirectory.primary.find(c=>c.region===mission.region);if(camera)openCameraToken(camera.id,mission);else openAgentPreview({mission});};
const originalDraftMetadata=window.draftModelMetadata;window.draftModelMetadata=form=>({...originalDraftMetadata(form),...(tokenCamera?{cameraId:tokenCamera.id,region:tokenCamera.region}:{})});
